const express = require('express');
const { authenticate } = require('./middleware/authenticate');
const invoices = require('./routes/invoices');
const profile = require('./routes/profile');
const admin = require('./routes/admin');
const app = express();
app.use('/api', authenticate);
app.use('/api/invoices', invoices);
app.use('/api/profile', profile);
app.use('/api/admin', admin);
module.exports = app;

async function byEmail(email) {
  return db.oneOrNone('select id from users where email = $1', [email]);
}
module.exports = { byEmail };

function authenticate(req, res, next) {
  const token = String(req.headers.authorization || '').replace(/^Bearer /, '');
  const claims = verifyJwt(token, process.env.JWT_SECRET, { algorithms: ['HS256'] });
  req.user = { id: claims.sub, tenantId: claims.tenant, role: claims.role };
  next();
}
module.exports = { authenticate };

async function findById(id) {
  return db.oneOrNone('select * from invoices where id = $1', [id]);
}
async function listForTenant(tenantId) {
  return db.any('select * from invoices where tenant_id = $1', [tenantId]);
}
module.exports = { findById, listForTenant };

async function update(id, fields) {
  return db.users.update({ id }, fields);
}
module.exports = { update };

const bcrypt = require('bcrypt');
async function verifyPassword(password, digest) { return bcrypt.compare(password, digest); }
module.exports = { verifyPassword };

const router = require('express').Router();
router.use((req, res, next) => req.user.role === 'admin' ? next() : res.sendStatus(403));
router.get('/stats', async (req, res) => res.json(await db.adminStats()));
module.exports = router;

const path = require('path');
const ROOT = path.resolve('/srv/avatars');
function avatarPath(name) {
  const candidate = path.resolve(ROOT, name);
  if (!candidate.startsWith(ROOT + path.sep)) throw new Error('outside avatar root');
  return candidate;
}
module.exports = { avatarPath };

const router = require('express').Router();
const invoices = require('../repos/invoices');
router.get('/:id', async (req, res) => {
  const invoice = await invoices.findById(req.params.id);
  if (!invoice) return res.sendStatus(404);
  return res.json(invoice);
});
module.exports = router;

const router = require('express').Router();
const users = require('../repos/users');
router.patch('/', async (req, res) => {
  const updated = await users.update(req.user.id, req.body);
  return res.json(updated);
});
module.exports = router;

